pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint depositAmount, uint cashOutAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount >= 1 ether);
        vm.assume(cashOutAmount > 0);
