pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 withdrawAmount) public {
        // Prepare user with some Ether
        vm.deal(user, 10 ether);

        // Scenario: deposit a reasonable amount first
        vm.assume(depositAmount >= 1 ether && depositAmount <= 10 ether);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(withdrawAmount > 0);

        vm.prank(user);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(user);

        vm.prank(user);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        uint256 balanceAfter = c.balances(user);

        if (success) {
            assertTrue(balanceAfter <= balanceBefore - withdrawAmount, "Balance should not increase after CashOut");
        } else {
            // If it reverts, balance must stay the same
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        }
    }
}

