pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 cashOutAmount) public {
        // Bound deposit to reasonable range, ensure caller is not zero
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        // Record initial total balance variable is not available, so we use a different approach
        // Instead, we check that the change in caller's balance equals negation of the change in contract balance
        // This is essentially conservation of total ether: contract.balance_change + caller.balance_change = 0
        // We drive: first deposit, then cashOut
        vm.deal(caller, depositAmount + 1 ether); // extra to cover possible gas?
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Now record balances before cashOut
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 contractBalanceBefore = address(c).balance;

        // Perform cashOut up to caller's balance
        cashOutAmount = bound(cashOutAmount, 0, callerBalanceBefore);
        vm.prank(caller);
        bool reverted = false;
        try c.CashOut(cashOutAmount) {
            // success
        } catch {
            reverted = true;
        }

        // The rule: if not reverted, the change in contract balance should be -cashOutAmount
        // i.e., contractBalanceAfter = contractBalanceBefore - cashOutAmount
        // Equivalently: (balance change) + cashOutAmount == 0

        // But we cannot read internal balances of caller after cashOut because they may have been sent ether; we check via contract balance
        if (!reverted) {
            // For correct C: balances[caller] is decremented by cashOutAmount, balance sum constant
            // So contract balance should decrease by cashOutAmount (if cashOutAmount <= contractBalanceBefore)
            // Actually cashOutAmount may be larger than contract balance? No, it's up to callerBalanceBefore which is <= contract balance?
            // Simple check: final contract balance should equal contractBalanceBefore - cashOutAmount
            assertTrue(address(c).balance == contractBalanceBefore - cashOutAmount, "Contract balance change does not match cashOut amount");
        } else {
            // If reverted, balance should remain unchanged
            assertTrue(address(c).balance == contractBalanceBefore, "Contract balance changed despite revert");
        }
    }
}

