pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0xABCD);

    function setUp() public {
        c = new C(address(this));
        vm.deal(alice, 100 ether);
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        // Bound deposit so that it can be either <= MinDeposit or > MinDeposit (1 ether)
        vm.assume(depositAmount > 0 && depositAmount <= 3 ether);
        // Bound withdraw to reasonable values
        vm.assume(withdrawAmount > 0 && withdrawAmount <= 3 ether);
        // Use an arbitrary caller; give them some ether
        vm.assume(caller != address(0) && caller != address(c));
        if (caller == address(this)) caller = address(0x1111);
        vm.deal(caller, 100 ether);

        // Record initial balance
        uint initialBalance = c.balances(caller);

        // Perform deposit
        vm.prank(caller);
        (bool successDeposit,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));

        // Perform withdrawal
        vm.prank(caller);
        bool successWithdraw = false;
        try c.CashOut(withdrawAmount) {
            successWithdraw = true;
        } catch {
            successWithdraw = false;
        }

        // Get final balance
        uint finalBalance = c.balances(caller);

        // The property: if deposit succeeded (msg.value > MinDeposit) and withdraw succeeded (withdrawAmount <= balance after deposit),
        // then final balance = initialBalance + depositAmount - withdrawAmount.
        // If deposit did not succeed (msg.value <= MinDeposit), balance unchanged; if withdraw reverted, balance unchanged after deposit.
        bool depositOk = depositAmount > c.MinDeposit();
        uint intermediateBalance = depositOk ? initialBalance + depositAmount : initialBalance;
        bool withdrawOk = (withdrawAmount <= intermediateBalance) && successWithdraw;
        uint expectedBalance = withdrawOk ? intermediateBalance - withdrawAmount : intermediateBalance;

        // For the reference, depositOk is strictly >; for the mutant, it's >=.
        // The property holds for reference but fails for mutant when depositAmount == c.MinDeposit().
        // So we assert that finalBalance == expectedBalance based on strict > condition.
        // If mutant is used, depositAmount == c.MinDeposit() will treat deposit as successful, changing expectedBalance, and the assertion will fail.
        assertTrue(finalBalance == expectedBalance, "Balance invariant violated");
    }
}

