        vm.assume(k != address(0));

        // Perform deposits
        vm.deal(caller1, depositAmt1);
        vm.prank(caller1);
        c.Deposit{value: depositAmt1}();

        vm.deal(caller2, depositAmt2);
        vm.prank(caller2);
        c.Deposit{value: depositAmt2}();

        vm.deal(caller3, depositAmt3);
        vm.prank(caller3);
        c.Deposit{value: depositAmt3}();

        // Perform a CashOut from caller1
        vm.prank(caller1);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("CashOut(uint256)", cashOutAmt));

